<?php $adminParams=[];?>
<div class="page-head"><div><span class="eyebrow"><?=e($business['name'])?></span><h1>GBP History</h1><p>Saved Google Business Profile totals and comparison reports.</p></div><a class="btn btn-primary" href="<?=url('business-gbp',$adminParams)?>">+ Add GBP Data</a></div>
