<?php foreach($entries as $row):?><tr><td><strong><?=e(date('M j',strtotime($row['period_start'])))?> – <?=e(date('M j, Y',strtotime($row['period_end'])))?></strong></td><td><?=e(ucfirst($row['frequency']))?></td><td><?=is_null($row['interactions'])?'—':numfmt($row['interactions'])?></td><td><?=is_null($row['total_reviews'])?'—':numfmt($row['total_reviews'])?></td><td><?=is_null($row['average_rating'])?'—':number_format((float)$row['average_rating'],1)?></td><td><?php $vm=report_validation_status_meta($row['validation_status']??'validated');?><span class="validation-badge validation-<?=e($vm['class'])?>"><?=e($vm['label'])?></span></td><td><?=e($row['entered_by_name'])?></td><td><div class="table-actions"><a class="btn btn-small" href="<?=url('business-gbp-report',['id'=>$row['id']]+$adminParams)?>">View</a><a class="btn btn-small" href="<?=url('business-gbp',['id'=>$row['id']]+$adminParams)?>">Edit</a><form method="post" action="<?=url('business-gbp-delete')?>" onsubmit="return confirm('Delete this GBP entry? This cannot be undone.');"><?=csrf_field()?><input type="hidden" name="id" value="<?=e($row['id'])?>"><?php if($adminParams):?><input type="hidden" name="business_id" value="<?=e($adminParams['business_id'])?>"><?php endif;?><button class="btn btn-small btn-danger" type="submit">Delete</button></form></div></td></tr><?php endforeach;?>
<?php if(!$entries):?><tr><td colspan="8" class="empty-cell">No GBP data has been entered yet.</td></tr><?php endif;?></tbody></table></div></section>
